cliProbes.jobBase:
type JobRunAt = Instant {}
action scan(at: JobRunAt) -> Unit {}

job overdue_reminders every 15m {
    concurrency: singleton
    run: scan(JobRunAt(clock.now))
    retry: next_schedule
}

cliProbes.routeBase:
route GET /deadline {
    auth: none
    deadline: DURATION
    action: {}
}
